  '99Chat プライバシーポリシー\n\n施行日：2026年5月24日\n\n99Chat（以下「当社」）は、お客様のプライバシーを尊重し、個人情報の保護に努めます。\n\n1. 収集する情報\n\n当社は、以下の情報を収集する場合があります。\n\n- 氏名およびプロフィール情報\n- メールアドレスおよび電話番号\n- 端末情報および IP アドレス\n- 利用状況データおよびアプリ分析データ\n- メッセージ内容およびアップロードされたコンテンツ\n- 決済情報（第三者決済事業者により安全に処理されます）\n\n2. 情報の利用目的\n\n収集した情報は、以下の目的で利用します。\n\n- サービスの提供および維持\n- ユーザー体験の向上\n- 不正行為および不適切な利用の防止\n- 決済処理\n- 更新情報および通知の送信\n- 法令上の義務への対応\n\n3. 情報の共有\n\n当社は、お客様の個人情報を販売しません。以下の場合に限り、情報を共有することがあります。\n\n- サービス提供事業者およびインフラパートナー\n- 決済処理事業者\n- 法令に基づき開示が必要な公的機関\n\n4. 保存期間\n\n当社は、業務、法令遵守、および安全管理の目的で必要な期間に限り、ユーザー情報を保持します。\n\n5. 安全管理\n\n当社は、業界標準の安全対策を講じてユーザー情報を保護します。ただし、いかなるシステムも完全な安全性を保証するものではありません。\n\n6. 国際的なデータ移転\n\nお客様の情報は、お客様の居住国または地域以外の国で処理・保存される場合があります。\n\n7. 未成年者のプライバシー\n\n99Chat は、18歳未満の方を対象としたサービスではありません。\n\n8. お客様の権利\n\nお住まいの地域の法令に基づき、お客様は以下の権利を有する場合があります。\n\n- ご自身のデータへのアクセス\n- 不正確なデータの訂正\n- データ削除の請求\n- 同意の撤回\n\n9. Cookie および分析ツール\n\n当社は、サービス品質向上のために、Cookie、分析ツール、その他これに類する技術を利用する場合があります。\n\n10. ポリシーの更新\n\n当社は、本ポリシーを随時更新する場合があります。\n\n11. お問い合わせ\n\nプライバシーに関するお問い合わせは、以下までご連絡ください。\n\nprivacy@99chat.app\n':
      '99Chat プライバシーポリシー\n\n施行日：2026年5月24日\n\n99Chat（以下「當社」）は、お客様のプライバシーを尊重し、個人情報の保護に努めます。\n\n1. 収集する情報\n\n當社は、以下の情報を収集する場合があります。\n\n- 氏名およびプロフィール情報\n- メールアドレスおよび電話番號\n- 端末情報および IP アドレス\n- 利用狀況データおよびアプリ分析データ\n- メッセージ內容およびアップロードされたコンテンツ\n- 決済情報（第三者決済事業者により安全に処理されます）\n\n2. 情報の利用目的\n\n収集した情報は、以下の目的で利用します。\n\n- サービスの提供および維持\n- ユーザー體験の向上\n- 不正行為および不適切な利用の防止\n- 決済処理\n- 更新情報および通知の送信\n- 法令上の義務への対応\n\n3. 情報の共有\n\n當社は、お客様の個人情報を販売しません。以下の場合に限り、情報を共有することがあります。\n\n- サービス提供事業者およびインフラパートナー\n- 決済処理事業者\n- 法令に基づき開示が必要な公的機関\n\n4. 儲存期間\n\n當社は、業務、法令遵守、および安全管理の目的で必要な期間に限り、ユーザー情報を保持します。\n\n5. 安全管理\n\n當社は、業界標準の安全対策を講じてユーザー情報を保護します。ただし、いかなるシステムも完全な安全性を保証するものではありません。\n\n6. 國際的なデータ移転\n\nお客様の情報は、お客様の居住國または地域以外の國で処理・儲存される場合があります。\n\n7. 未成年者のプライバシー\n\n99Chat は、18歳未満の方を対象としたサービスではありません。\n\n8. お客様の権利\n\nお住まいの地域の法令に基づき、お客様は以下の権利を有する場合があります。\n\n- ご自身のデータへのアクセス\n- 不正確なデータの訂正\n- データ削除の請求\n- 同意の撤回\n\n9. Cookie および分析ツール\n\n當社は、サービス品質向上のために、Cookie、分析ツール、その他これに類する技術を利用する場合があります。\n\n10. ポリシーの更新\n\n當社は、本ポリシーを隨時更新する場合があります。\n\n11. お問い合わせ\n\nプライバシーに関するお問い合わせは、以下までご連絡ください。\n\nprivacy@99chat.app\n',
  '99Chat 利用規約\n\n施行日：2026年5月24日\n\n99Chat（以下「99Chat」または「当社」）のアプリ、ウェブサイト、および関連サービス（以下総称して「本サービス」）をご利用いただきありがとうございます。本サービスにアクセスまたは利用することにより、お客様は本利用規約（以下「本規約」）に拘束されることに同意したものとみなされます。\n\n1. 利用資格\n\n本サービスを利用するには、18歳以上であるか、またはお住まいの地域で法的に成人と認められる年齢に達している必要があります。\n\n2. アカウント登録\n\nお客様は、ご自身のアカウント認証情報を適切に管理し、当該アカウントの下で行われるすべての行為について責任を負うものとします。\n\n3. 適正な利用\n\nお客様は、以下の行為を行わないことに同意します。\n\n- 適用される法令または規制に違反すること\n- 他者への嫌がらせ、侮辱、脅迫、またはなりすまし\n- 悪意のあるソフトウェアや有害なコンテンツのアップロード\n- 詐欺、スパム送信、その他の違法行為\n- 著作権で保護されたコンテンツを無断で配布すること\n\n4. ユーザーコンテンツ\n\nユーザーは、自ら投稿したコンテンツの権利を保持します。本サービスを通じてコンテンツを投稿することにより、お客様は、サービスの運営および改善に必要な範囲で、当該コンテンツを使用、表示、配布するための、全世界対象、非独占的、無償のライセンスを 99Chat に付与するものとします。\n\n5. プライバシー\n\n本サービスの利用には、当社のプライバシーポリシーも適用されます。\n\n6. 知的財産権\n\nすべての商標、ロゴ、ブランド、ソフトウェア、およびプラットフォーム上のコンテンツは、99Chat またはそのライセンサーに帰属します。\n\n7. サブスクリプションおよび支払い\n\n一部の機能は、有料またはサブスクリプション契約が必要となる場合があります。法令で別段の定めがある場合を除き、支払い済みの料金は返金されません。\n\n8. 利用停止および終了\n\nお客様が本規約に違反した場合、99Chat はいつでも本サービスへのアクセスを停止または終了することができます。\n\n9. 免責事項\n\n本サービスは「現状有姿」かつ「提供可能な範囲」で提供され、いかなる種類の保証も伴いません。\n\n10. 責任の制限\n\nお客様による本サービスの利用に起因して発生する間接損害、付随的損害、特別損害、または結果的損害について、99Chat は責任を負いません。\n\n11. 規約の変更\n\n当社は、本規約を随時更新する場合があります。更新後も本サービスを継続して利用することにより、改定後の規約に同意したものとみなされます。\n\n12. お問い合わせ\n\n本規約に関するご質問は、以下までお問い合わせください。\n\nsupport@99chat.app\n':
      '99Chat 利用規約\n\n施行日：2026年5月24日\n\n99Chat（以下「99Chat」または「當社」）のアプリ、ウェブサイト、および関連サービス（以下総稱して「本サービス」）をご利用いただきありがとうございます。本サービスにアクセスまたは利用することにより、お客様は本利用規約（以下「本規約」）に拘束されることに同意したものとみなされます。\n\n1. 利用資格\n\n本サービスを利用するには、18歳以上であるか、またはお住まいの地域で法的に成人と認められる年齢に達している必要があります。\n\n2. アカウント登録\n\nお客様は、ご自身のアカウント認証情報を適切に管理し、當該アカウントの下で行われるすべての行為について責任を負うものとします。\n\n3. 適正な利用\n\nお客様は、以下の行為を行わないことに同意します。\n\n- 適用される法令または規制に違反すること\n- 他者への嫌がらせ、侮辱、脅迫、またはなりすまし\n- 悪意のあるソフトウェアや有害なコンテンツのアップロード\n- 詐欺、スパム送信、その他の違法行為\n- 著作権で保護されたコンテンツを無斷で配布すること\n\n4. ユーザーコンテンツ\n\nユーザーは、自ら投稿したコンテンツの権利を保持します。本サービスを通じてコンテンツを投稿することにより、お客様は、サービスの運営および改善に必要な範囲で、當該コンテンツを使用、表示、配布するための、全世界対象、非獨佔的、無償のライセンスを 99Chat に付與するものとします。\n\n5. プライバシー\n\n本サービスの利用には、當社のプライバシーポリシーも適用されます。\n\n6. 知的財産権\n\nすべての商標、ロゴ、ブランド、ソフトウェア、およびプラットフォーム上のコンテンツは、99Chat またはそのライセンサーに帰屬します。\n\n7. サブスクリプションおよび支払い\n\n一部の機能は、有料またはサブスクリプション契約が必要となる場合があります。法令で別段の定めがある場合を除き、支払い済みの料金は返金されません。\n\n8. 利用停止および終了\n\nお客様が本規約に違反した場合、99Chat はいつでも本サービスへのアクセスを停止または終了することができます。\n\n9. 免責事項\n\n本サービスは「現狀有姿」かつ「提供可能な範囲」で提供され、いかなる種類の保証も伴いません。\n\n10. 責任の制限\n\nお客様による本サービスの利用に起因して発生する間接損害、付隨的損害、特別損害、または結果的損害について、99Chat は責任を負いません。\n\n11. 規約の変更\n\n當社は、本規約を隨時更新する場合があります。更新後も本サービスを継続して利用することにより、改定後の規約に同意したものとみなされます。\n\n12. お問い合わせ\n\n本規約に関するご質問は、以下までお問い合わせください。\n\nsupport@99chat.app\n',
  '99Chat 服务条款\n\n生效日期：2026 年 5 月 24 日\n\n欢迎您使用 99Chat（“99Chat”、“我们”）应用、网站及相关服务（统称“服务”）。当您访问或使用本服务时，即表示您同意接受本《服务条款》（以下简称“条款”）的约束。\n\n1. 资格要求\n\n您必须年满 18 周岁，或达到您所在司法辖区规定的法定成年年龄，方可使用本服务。\n\n2. 账号注册\n\n您有责任妥善保管您的账号凭证，并对您账号下发生的全部活动承担责任。\n\n3. 合理使用\n\n您同意不会：\n\n- 违反任何适用法律法规\n- 骚扰、辱骂、威胁或冒充他人\n- 上传恶意软件或有害内容\n- 从事欺诈、垃圾信息传播或其他非法活动\n- 未经授权分发受版权保护的内容\n\n4. 用户内容\n\n用户对其提交的内容保留所有权。通过本服务发布内容时，您授予 99Chat 一项全球范围内、非独占、免版税的许可，以便仅为运营和改进服务之目的使用、展示和分发相关内容。\n\n5. 隐私\n\n您对本服务的使用还受到《隐私政策》的约束。\n\n6. 知识产权\n\n所有商标、标识、品牌、软件和平台内容均归 99Chat 或其许可方所有。\n\n7. 订阅与支付\n\n部分功能可能需要付费或订阅。除法律另有规定外，所有付款均不予退款。\n\n8. 终止\n\n如果您违反本条款，99Chat 有权随时暂停或终止您对服务的访问权限。\n\n9. 免责声明\n\n本服务按“现状”和“可用”状态提供，不附带任何形式的保证。\n\n10. 责任限制\n\n对于因您使用本服务而产生的任何间接、附带、特殊或后果性损害，99Chat 不承担责任。\n\n11. 条款变更\n\n我们可能会不时更新本条款。在条款更新后继续使用服务，即视为您接受修订后的内容。\n\n12. 联系方式\n\n如对本条款有任何疑问，请联系：\n\nsupport@99chat.app\n':
      '99Chat 服務條款\n\n生效日期：2026 年 5 月 24 日\n\n歡迎您使用 99Chat（“99Chat”、“我們”）應用、網站及相關服務（統稱“服務”）。當您訪問或使用本服務時，即表示您同意接受本《服務條款》（以下簡稱“條款”）的約束。\n\n1. 資格要求\n\n您必須年滿 18 週歲，或達到您所在司法轄區規定的法定成年年齡，方可使用本服務。\n\n2. 賬號註冊\n\n您有責任妥善保管您的賬號憑證，並對您賬號下發生的全部活動承擔責任。\n\n3. 合理使用\n\n您同意不會：\n\n- 違反任何適用法律法規\n- 騷擾、辱罵、威脅或冒充他人\n- 上傳惡意軟體或有害內容\n- 從事欺詐、垃圾資訊傳播或其他非法活動\n- 未經授權分發受版權保護的內容\n\n4. 使用者內容\n\n使用者對其提交的內容保留所有權。透過本服務釋出內容時，您授予 99Chat 一項全球範圍內、非獨佔、免版稅的許可，以便僅為運營和改進服務之目的使用、展示和分發相關內容。\n\n5. 隱私\n\n您對本服務的使用還受到《隱私政策》的約束。\n\n6. 智慧財產權\n\n所有商標、標識、品牌、軟體和平臺內容均歸 99Chat 或其許可方所有。\n\n7. 訂閱與支付\n\n部分功能可能需要付費或訂閱。除法律另有規定外，所有付款均不予退款。\n\n8. 終止\n\n如果您違反本條款，99Chat 有權隨時暫停或終止您對服務的訪問許可權。\n\n9. 免責宣告\n\n本服務按“現狀”和“可用”狀態提供，不附帶任何形式的保證。\n\n10. 責任限制\n\n對於因您使用本服務而產生的任何間接、附帶、特殊或後果性損害，99Chat 不承擔責任。\n\n11. 條款變更\n\n我們可能會不時更新本條款。在條款更新後繼續使用服務，即視為您接受修訂後的內容。\n\n12. 聯絡方式\n\n如對本條款有任何疑問，請聯絡：\n\nsupport@99chat.app\n',
