  '99Chat 隐私政策\n\n生效日期：2026 年 5 月 24 日\n\n99Chat（“我们”）尊重您的隐私，并致力于保护您的个人信息安全。\n\n1. 我们收集的信息\n\n我们可能会收集以下信息：\n\n- 姓名与个人资料信息\n- 邮箱地址和手机号码\n- 设备信息与 IP 地址\n- 使用数据与应用分析数据\n- 消息内容与您上传的资料\n- 支付信息（由第三方支付服务商安全处理）\n\n2. 信息的使用方式\n\n我们收集信息用于：\n\n- 提供和维护服务\n- 提升用户体验\n- 防止欺诈和滥用\n- 处理支付事务\n- 发送更新和通知\n- 履行法律义务\n\n3. 信息共享\n\n我们不会出售您的个人信息。我们可能会与以下主体共享信息：\n\n- 服务提供商和基础设施合作伙伴\n- 支付处理机构\n- 法律法规要求的有关机关\n\n4. 数据保存期限\n\n我们仅在业务、法律和安全目的所必需的期限内保留用户信息。\n\n5. 安全措施\n\n我们采取行业通行的安全措施保护用户信息，但任何系统都无法保证绝对安全。\n\n6. 跨境传输\n\n您的信息可能会在您所在司法辖区之外的国家或地区被处理和存储。\n\n7. 未成年人隐私\n\n99Chat 不面向 18 周岁以下用户提供服务。\n\n8. 您的权利\n\n依据您所在地区的法律，您可能享有以下权利：\n\n- 访问您的数据\n- 更正不准确的数据\n- 请求删除数据\n- 撤回授权同意\n\n9. Cookies 与分析工具\n\n我们可能会使用 Cookies、分析工具及类似技术来改进服务体验。\n\n10. 政策更新\n\n我们可能会不定期更新本隐私政策。\n\n11. 联系我们\n\n如您有与隐私相关的问题，请联系：\n\nprivacy@99chat.app\n':
      '99Chat 隱私政策\n\n生效日期：2026 年 5 月 24 日\n\n99Chat（“我們”）尊重您的隱私，並致力於保護您的個人資訊保安。\n\n1. 我們收集的資訊\n\n我們可能會收集以下資訊：\n\n- 姓名與個人資料資訊\n- 郵箱地址和手機號碼\n- 裝置資訊與 IP 地址\n- 使用資料與應用分析資料\n- 訊息內容與您上傳的資料\n- 支付資訊（由第三方支付服務商安全處理）\n\n2. 資訊的使用方式\n\n我們收集資訊用於：\n\n- 提供和維護服務\n- 提升使用者體驗\n- 防止欺詐和濫用\n- 處理支付事務\n- 傳送更新和通知\n- 履行法律義務\n\n3. 資訊共享\n\n我們不會出售您的個人資訊。我們可能會與以下主體共享資訊：\n\n- 服務提供商和基礎設施合作伙伴\n- 支付處理機構\n- 法律法規要求的有關機關\n\n4. 資料儲存期限\n\n我們僅在業務、法律和安全目的所必需的期限內保留使用者資訊。\n\n5. 安全措施\n\n我們採取行業通行的安全措施保護使用者資訊，但任何系統都無法保證絕對安全。\n\n6. 跨境傳輸\n\n您的資訊可能會在您所在司法轄區之外的國家或地區被處理和儲存。\n\n7. 未成年人隱私\n\n99Chat 不面向 18 週歲以下使用者提供服務。\n\n8. 您的權利\n\n依據您所在地區的法律，您可能享有以下權利：\n\n- 訪問您的資料\n- 更正不準確的資料\n- 請求刪除資料\n- 撤回授權同意\n\n9. Cookies 與分析工具\n\n我們可能會使用 Cookies、分析工具及類似技術來改進服務體驗。\n\n10. 政策更新\n\n我們可能會不定期更新本隱私政策。\n\n11. 聯絡我們\n\n如您有與隱私相關的問題，請聯絡：\n\nprivacy@99chat.app\n',
