  '在「我的」-「设置」-「账号安全」-「登录设备」查看设备记录。发现陌生设备时，退出该设备并修改登录密码。若无法操作，请把提示信息发给客服，不要提供密码或验证码。':
      '在「我的」-「設定」-「賬號安全」-「登入裝置」檢視裝置記錄。發現陌生裝置時，退出該裝置並修改登入密碼。若無法操作，請把提示資訊發給客服，不要提供密碼或驗證碼。',
  '在「我的」-「设置」-「账号安全」中修改登录密码，按页面要求完成验证。修改后使用新密码登录。建议使用独立的登录密码，不要与支付密码相同。':
      '在「我的」-「設定」-「賬號安全」中修改登入密碼，按頁面要求完成驗證。修改後使用新密碼登入。建議使用獨立的登入密碼，不要與支付密碼相同。',
  '在「我的」-「设置」-「账号安全」中绑定或更换手机号，按页面流程验证旧号码和新号码。无法收到验证码时，检查号码、区号、信号及短信拦截；旧号码已停用可向客服说明情况。':
      '在「我的」-「設定」-「賬號安全」中繫結或更換手機號，按頁面流程驗證舊號碼和新號碼。無法收到驗證碼時，檢查號碼、區號、訊號及簡訊攔截；舊號碼已停用可向客服說明情況。',
  '在下方说明发生时间、相关公开账号或群号、问题经过，并提供必要截图。涉及账号安全时请先保护账号。不要在投诉内容中发送密码、支付密码或验证码。':
      '在下方說明發生時間、相關公開賬號或群號、問題經過，並提供必要截圖。涉及賬號安全時請先保護賬號。不要在投訴內容中傳送密碼、支付密碼或驗證碼。',
  '在下方输入问题即可联系人工客服。可发送文字或页面支持的附件；客服连接和发送结果以页面提示为准。请保留有用的提示信息，客服不会索取密码或验证码。':
      '在下方輸入問題即可聯絡人工客服。可傳送文字或頁面支援的附件；客服連線和傳送結果以頁面提示為準。請保留有用的提示資訊，客服不會索取密碼或驗證碼。',
  '在会话页点击右上角加号，选择发起群聊并选择联系人，按页面提示创建。群名称、公告和成员管理可在群资料或群设置中调整，操作权限取决于你的群角色。':
      '在會話頁點選右上角加號，選擇發起群聊並選擇聯絡人，按頁面提示建立。群名稱、公告和成員管理可在群資料或群設定中調整，操作許可權取決於你的群角色。',
  '在地图上选点，或定位到当前位置': '在地圖上選點，或定位到當前位置',
  '在应用内打开': '在應用內開啟',
  '在登录页选择找回密码，使用已绑定的手机号或邮箱，按页面要求验证后重置。如果已无法使用绑定的号码或邮箱，请在下方说明情况，由客服告知核实流程。':
      '在登入頁選擇找回密碼，使用已繫結的手機號或郵箱，按頁面要求驗證後重置。如果已無法使用繫結的號碼或郵箱，請在下方說明情況，由客服告知核實流程。',
  '在登录页选择注册，按页面流程填写信息并完成验证。使用本人可接收验证码的号码或邮箱，妥善保管登录密码，验证码不要转发给任何人。':
      '在登入頁選擇註冊，按頁面流程填寫資訊並完成驗證。使用本人可接收驗證碼的號碼或郵箱，妥善保管登入密碼，驗證碼不要轉發給任何人。',
