  '核对手机号、区号或邮箱地址，检查信号、短信拦截和垃圾邮件。倒计时结束后再尝试获取，短时间频繁请求可能受到限制。请勿把验证码发给他人，包括客服。':
      '核對手機號、區號或郵箱地址，檢查訊號、簡訊攔截和垃圾郵件。倒計時結束後再嘗試獲取，短時間頻繁請求可能受到限制。請勿把驗證碼發給他人，包括客服。',
