  '检查相册或相机权限，以及网络连接。聊天中可通过加号选择图片或视频；失败时点击感叹号重试。如果文件过大或格式不支持，可尝试较小的文件，并向客服提供提示内容。':
      '檢查相簿或相機許可權，以及網路連線。聊天中可透過加號選擇圖片或影片；失敗時點選感嘆號重試。如果檔案過大或格式不支援，可嘗試較小的檔案，並向客服提供提示內容。',
  '检查网络、余额和支付密码，并查看红包页面的提示。领取时确认红包是否已领完、过期或不符合领取条件。持续失败时，向客服提供相关订单编号或提示截图。':
      '檢查網路、餘額和支付密碼，並檢視紅包頁面的提示。領取時確認紅包是否已領完、過期或不符合領取條件。持續失敗時，向客服提供相關訂單編號或提示截圖。',
  '检查网络后重试': '檢查網路後重試',
